<script lang="ts">let {data}=$props();let message=$state('');let busy=$state(false);async function retry(key:string){busy=true;try{const response=await fetch('/workspace/uploads?retry='+encodeURIComponent(key),{method:'POST'});const result=await response.json();message=response.ok?'处理结果：'+result.state:result.error??'重试失败，请检查处理记录';}catch{message='请求失败，请重试';}finally{busy=false;}}async function upload(event:SubmitEvent){event.preventDefault();busy=true;message='';try{const file=new FormData(event.currentTarget as HTMLFormElement).get('file');if(!(file instanceof File)||!file.size){message='请选择文件';return;}const response=await fetch('/workspace/uploads',{method:'POST',headers:{'x-file-name':encodeURIComponent(file.name),'content-type':file.type||'application/octet-stream'},body:file});const result=await response.json();message=response.ok?'上传已接收，刷新列表查看处理结果':result.error??'上传失败，请重试';}catch{message='连接失败，文件选择已保留，请重试';}finally{busy=false;}}</script>
<svelte:head><title>媒体 · 站长工作台</title></svelte:head><main><h1>媒体</h1><p>原图默认受保护。上传成功不代表获得公开展示授权；在内容发布时确认所用媒体。</p><form onsubmit={upload}><label>选择图片<input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/gif" required/></label><button disabled={busy}>{busy?'上传中…':'上传图片'}</button></form>{#if message}<p role="status">{message}</p>{/if}<a href="/workspace/media">刷新列表</a><p>共 {data.total} 条</p><ul>{#each data.items as item}<li><strong>{item.name}</strong><p>{item.state} · {item.bytes} 字节</p><p>媒体键：{item.key}</p>{#if item.state!=='ready'}<button disabled={busy} onclick={()=>retry(String(item.key))}>重试处理</button>{/if}{#if item.error}<p role="alert">处理失败：{item.error}</p>{/if}</li>{/each}</ul>{#if !data.items.length}<p>尚无媒体。</p>{/if}<nav>{#if data.page>1}<a href={`?page=${data.page-1}`}>上一页</a>{/if}{#if data.page*20<data.total}<a href={`?page=${data.page+1}`}>下一页</a>{/if}</nav></main><style>li{overflow-wrap:anywhere;padding:16px;border-bottom:1px solid var(--line)}nav{display:flex;gap:24px}</style>
